S_prime = range(1, 21)
valid_triplets = set()
triples_found = []

# Iterate over distinct a, b, c in S'
for a in S_prime:
    for b in S_prime:
        if a == b:
            continue
        for c in S_prime:
            if c == a or c == b:
                continue

            # Calculate potential x, y, z
            x = a + b
            y = b + c
            z = c + a

            # Check if x, y, z are in S' (i.e., <= 20)
            if x > 20 or y > 20 or z > 20:
                continue

            # Check if x, y, z are distinct (they should be if a, b, c are distinct)
            if x == y or y == z or x == z:
                # This should theoretically not happen if a, b, c are distinct positive integers
                # Check for robustness anyway
                continue

            # Store the canonical representation of the set {x, y, z}
            # Sorting ensures uniqueness regardless of (a, b, c) ordering
            triplet = tuple(sorted((x, y, z)))

            if triplet not in valid_triplets:
                valid_triplets.add(triplet)
                # Store the details for verification
                triples_found.append({
                    "triplet": triplet,
                    "a": a, "b": b, "c": c
                })

print(f"Total number of unique sets {{x, y, z}} found in S': {len(valid_triplets)}")
# Print a sample of the found triplets and their generating a, b, c
